// StudentApplications.jsx

import { useState } from "react";
import StudentLayout from "./StudentLayout";

const APPLICATIONS = [
  {
    id:1, company:"Sonatrach Digital", logo:"🛢️", role:"Full-Stack Developer",
    wilaya:"Alger", type:"On-site", duration:"6 months",
    appliedDate:"Apr 20, 2025", status:"pending",
    skills:["React","Node.js","PostgreSQL"],
    timeline:[
      { label:"Applied",           date:"Apr 20", done:true  },
      { label:"Profile reviewed",  date:"Apr 22", done:true  },
      { label:"Company decision",  date:"—",       done:false },
      { label:"Admin validation",  date:"—",       done:false },
      { label:"Agreement generated",date:"—",      done:false },
    ]
  },
  {
    id:2, company:"Ooredoo Labs",     logo:"🌐", role:"Data Analyst",
    wilaya:"Alger", type:"Hybrid",   duration:"4 months",
    appliedDate:"Apr 12, 2025", status:"accepted",
    skills:["Python","SQL","Power BI"],
    timeline:[
      { label:"Applied",            date:"Apr 12", done:true  },
      { label:"Profile reviewed",   date:"Apr 14", done:true  },
      { label:"Company decision",   date:"Apr 17", done:true  },
      { label:"Admin validation",   date:"Apr 19", done:true  },
      { label:"Agreement generated",date:"Apr 20", done:true  },
    ]
  },
  {
    id:3, company:"BNA Digital",     logo:"🏦", role:"Backend Intern",
    wilaya:"Alger", type:"On-site",  duration:"3 months",
    appliedDate:"Apr 5, 2025", status:"refused",
    skills:["Java","Spring Boot","SQL"],
    timeline:[
      { label:"Applied",           date:"Apr 5",  done:true  },
      { label:"Profile reviewed",  date:"Apr 7",  done:true  },
      { label:"Company decision",  date:"Apr 10", done:true  },
      { label:"Admin validation",  date:"—",      done:false },
      { label:"Agreement generated",date:"—",     done:false },
    ]
  },
  {
    id:4, company:"Djezzy Tech",      logo:"📡", role:"Backend Engineer",
    wilaya:"Alger", type:"Hybrid",   duration:"4 months",
    appliedDate:"Mar 28, 2025", status:"pending",
    skills:["Python","Django","Redis"],
    timeline:[
      { label:"Applied",           date:"Mar 28", done:true  },
      { label:"Profile reviewed",  date:"—",      done:false },
      { label:"Company decision",  date:"—",      done:false },
      { label:"Admin validation",  date:"—",      done:false },
      { label:"Agreement generated",date:"—",     done:false },
    ]
  },
];

const STATUS = {
  pending:  { label:"Pending",  dot:"bg-amber-400",  badge:"badge-orange", text:"Awaiting company response" },
  accepted: { label:"Accepted", dot:"bg-emerald-400", badge:"badge-green",  text:"Congratulations! Agreement being prepared." },
  refused:  { label:"Refused",  dot:"bg-red-400",     badge:"badge-red",    text:"Application was not selected." },
};

const TABS = ["All","Pending","Accepted","Refused"];

function AppCard({ app, onSelect, selected }) {
  const s = STATUS[app.status];
  return (
    <div
      onClick={() => onSelect(app)}
      className={`card border cursor-pointer p-4 transition-all ${
        selected ? "border-blue-400 bg-blue-50/40" : "border-slate-200"
      } offer-card`}
    >
      <div className="flex items-start gap-3 mb-3">
        <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-lg shrink-0">{app.logo}</div>
        <div className="flex-1 min-w-0">
          <h3 className="font-syne font-bold text-slate-800 text-sm truncate">{app.role}</h3>
          <p className="text-xs text-slate-400">{app.company} · {app.wilaya}</p>
        </div>
        <span className={`badge ${s.badge} shrink-0`}>{s.label}</span>
      </div>
      <div className="flex flex-wrap gap-1.5 mb-3">
        {app.skills.map(sk => <span key={sk} className="skill-chip">{sk}</span>)}
      </div>
      <div className="flex justify-between items-center text-xs text-slate-400">
        <span>Applied {app.appliedDate}</span>
        <span>{app.type} · {app.duration}</span>
      </div>
    </div>
  );
}function Timeline({ steps, status }) {
  return (
    <div className="space-y-0">
      {steps.map((step, i) => {
        const isLast = i === steps.length - 1;
        const isRefused = status === "refused" && i === 2 && step.done;
        return (
          <div key={i} className="flex gap-3">
            <div className="flex flex-col items-center">
              <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold border-2 shrink-0 ${
                isRefused
                  ? "bg-red-100 border-red-400 text-red-600"
                  : step.done
                  ? "bg-blue-500 border-blue-500 text-white"
                  : "bg-white border-slate-200 text-slate-300"
              }`}>
                {isRefused ? "✕" : step.done ? "✓" : i + 1}
              </div>
              {!isLast && (
                <div className={`w-0.5 h-8 mt-1 ${step.done && !isRefused ? "bg-blue-200" : "bg-slate-100"}`} />
              )}
            </div>
            <div className="pb-4 flex-1">
              <div className={`text-sm font-semibold ${isRefused ? "text-red-600" : step.done ? "text-slate-800" : "text-slate-400"}`}>
                {step.label}
              </div>
              <div className="text-xs text-slate-400 mt-0.5">{step.date}</div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default function StudentApplications() {
  const [tab, setTab]         = useState("All");
  const [selected, setSelected] = useState(APPLICATIONS[0]);

  const filtered = tab === "All"
    ? APPLICATIONS
    : APPLICATIONS.filter(a => STATUS[a.status].label === tab);

  return (
    <StudentLayout active="applications">
      <div className="p-5 md:p-8">

        {/* Header */}
        <div className="anim-fade-up mb-6">
          <p className="text-xs font-semibold text-blue-500 uppercase tracking-widest mb-1">Tracking</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">My applications</h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">{APPLICATIONS.length} total · {APPLICATIONS.filter(a=>a.status==="accepted").length} accepted</p>
        </div>

        {/* Tabs */}
        <div className="anim-fade-up anim-d1 flex gap-1 bg-slate-100 rounded-xl p-1 w-fit mb-5">
          {TABS.map(t => (
            <button 
              key={t} 
              onClick={() => setTab(t)} 
              className={`tab-btn ${tab===t?"active":"inactive"}`}
            >
              {t}
            </button>
          ))}
        </div>

        <div className="grid md:grid-cols-5 gap-5">

          {/* Left — list */}
          <div className="md:col-span-2 anim-fade-up anim-d2 space-y-3">
            {filtered.length > 0 ? filtered.map(app => (
              <AppCard key={app.id} app={app} onSelect={setSelected} selected={selected?.id === app.id} />
            )) : (
              <div className="text-center py-12">
                <div className="text-4xl mb-2">📭</div>
                <p className="text-sm text-slate-400">No {tab.toLowerCase()} applications.</p>
              </div>
            )}
          </div>

          {/* Right — detail */}
          <div className="md:col-span-3 anim-fade-up anim-d3">
            {selected ? (
              <div className="card border border-slate-200 p-5 sticky top-4">
                {/* Company header */}
                <div className="flex items-start gap-4 mb-5 pb-5 border-b border-slate-100">
                  <div className="w-14 h-14 rounded-2xl bg-slate-100 flex items-center justify-center text-3xl shrink-0">{selected.logo}</div>
                  <div className="flex-1">
                    <h2 className="font-syne font-extrabold text-slate-900 text-xl">{selected.role}</h2><p className="text-sm text-slate-500">{selected.company}</p>
                    <div className="flex flex-wrap gap-2 mt-2">
                      <span className={`badge ${STATUS[selected.status].badge}`}>{STATUS[selected.status].label}</span>
                      <span className="badge badge-slate">{selected.type}</span>
                      <span className="badge badge-slate">⏱ {selected.duration}</span>
                    </div>
                  </div>
                </div>

                {/* Status message */}
                <div className={`rounded-xl p-3 mb-5 text-sm font-medium flex items-center gap-2 ${
                  selected.status==="accepted" ? "bg-emerald-50 text-emerald-700 border border-emerald-200" :
                  selected.status==="refused"  ? "bg-red-50 text-red-700 border border-red-200" :
                  "bg-amber-50 text-amber-700 border border-amber-200"
                }`}>
                  <span>{selected.status==="accepted"?"✅":selected.status==="refused"?"❌":"⏳"}</span>
                  {STATUS[selected.status].text}
                </div>

                {/* Details */}
                <div className="grid grid-cols-2 gap-3 mb-5">
                  {[
                    { k:"Company",  v:selected.company },
                    { k:"Location", v:`${selected.wilaya} · ${selected.type}` },
                    { k:"Duration", v:selected.duration },
                    { k:"Applied",  v:selected.appliedDate },
                  ].map(({k,v})=>(
                    <div key={k} className="bg-slate-50 rounded-xl p-3">
                      <div className="text-xs text-slate-400 mb-0.5">{k}</div>
                      <div className="text-sm font-semibold text-slate-700">{v}</div>
                    </div>
                  ))}
                </div>

                {/* Skills */}
                <div className="mb-5">
                  <h4 className="text-xs font-semibold text-slate-500 uppercase tracking-widest mb-2">Required skills</h4>
                  <div className="flex flex-wrap gap-1.5">
                    {selected.skills.map(s=><span key={s} className="skill-chip">{s}</span>)}
                  </div>
                </div>

                {/* Timeline */}
                <div>
                  <h4 className="text-xs font-semibold text-slate-500 uppercase tracking-widest mb-4">Application timeline</h4>
                  <Timeline steps={selected.timeline} status={selected.status} />
                </div>

                {/* Action */}
                {selected.status==="accepted" && (
                  <div className="mt-4 pt-4 border-t border-slate-100">
                    <button className="w-full shimmer-btn text-white font-semibold py-3 rounded-xl text-sm">
                      📄 Download Convention de Stage
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="card border border-slate-200 p-8 text-center">
                <div className="text-4xl mb-3">👆</div>
                <p className="text-sm text-slate-400">Select an application to see details.</p>
              </div>
            )}
          </div>

        </div>
      </div>
    </StudentLayout>
  );
}
